package dev.pongy.app;
import android.app.*;import android.os.*;import android.content.*;import android.content.pm.PackageManager;import android.net.Uri;import android.webkit.*;import android.view.*;import android.Manifest;
public final class MainActivity extends Activity {
 private WebView web;private ValueCallback<Uri[]> files;private PermissionRequest microphone;
 private static final String ORIGIN="https://pongy-ai.devs.surf";
 private boolean trusted(String url){return url!=null&&(url.equals(ORIGIN)||url.startsWith(ORIGIN+"/"));}
 private void external(String url){if(url!=null&&url.startsWith("https://"))try{startActivity(new Intent(Intent.ACTION_VIEW,Uri.parse(url)));}catch(ActivityNotFoundException e){new AlertDialog.Builder(this).setMessage("A browser is required to open this link.").setPositiveButton("OK",null).show();}}
 @Override public void onCreate(Bundle state){super.onCreate(state);web=new WebView(this);setContentView(web);getWindow().setSoftInputMode(WindowManager.LayoutParams.SOFT_INPUT_ADJUST_RESIZE);web.setOnApplyWindowInsetsListener((v,insets)->{v.setPadding(insets.getSystemWindowInsetLeft(),insets.getSystemWindowInsetTop(),insets.getSystemWindowInsetRight(),insets.getSystemWindowInsetBottom());return insets.consumeSystemWindowInsets();});web.requestApplyInsets();web.addJavascriptInterface(new AppSettingsBridge(),"PongyAndroid");WebSettings s=web.getSettings();s.setJavaScriptEnabled(true);s.setDomStorageEnabled(true);s.setAllowFileAccess(false);s.setAllowContentAccess(false);s.setMixedContentMode(WebSettings.MIXED_CONTENT_NEVER_ALLOW);s.setJavaScriptCanOpenWindowsAutomatically(false);s.setSupportMultipleWindows(true);s.setUserAgentString(s.getUserAgentString()+" PongyNative/0.19.0 Android");CookieManager.getInstance().setAcceptCookie(true);CookieManager.getInstance().setAcceptThirdPartyCookies(web,false);
 web.setWebViewClient(new WebViewClient(){@Override public void onReceivedError(WebView v,WebResourceRequest request,WebResourceError error){int code=error.getErrorCode();if(request.isForMainFrame()&&trusted(request.getUrl().toString())&&(code==ERROR_HOST_LOOKUP||code==ERROR_CONNECT||code==ERROR_TIMEOUT||code==ERROR_IO))showOffline();}@Override public boolean shouldOverrideUrlLoading(WebView v,WebResourceRequest request){String url=request.getUrl().toString();if(trusted(url))return false;external(url);return true;}@Override public void onPageFinished(WebView v,String url){if(trusted(url))v.evaluateJavascript("window.PongyNative=Object.freeze({platform:'android',version:'0.19.0',scopedFiles:true});window.dispatchEvent(new Event('pongy-native-ready'));",null);CookieManager.getInstance().flush();}@Override public void onReceivedSslError(WebView v,android.webkit.SslErrorHandler handler,android.net.http.SslError error){handler.cancel();}});
 web.setWebChromeClient(new WebChromeClient(){@Override public boolean onShowFileChooser(WebView v,ValueCallback<Uri[]> callback,FileChooserParams params){if(!trusted(v.getUrl()))return false;if(files!=null)files.onReceiveValue(null);files=callback;Intent pick=new Intent(Intent.ACTION_OPEN_DOCUMENT);pick.addCategory(Intent.CATEGORY_OPENABLE);pick.setType("*/*");pick.putExtra(Intent.EXTRA_ALLOW_MULTIPLE,params.getMode()==FileChooserParams.MODE_OPEN_MULTIPLE);try{startActivityForResult(pick,41);}catch(ActivityNotFoundException e){files.onReceiveValue(null);files=null;}return true;}
 @Override public void onPermissionRequest(PermissionRequest request){runOnUiThread(()->{if(!trusted(request.getOrigin().toString())||!trusted(web.getUrl())){request.deny();return;}String[] resources=request.getResources();if(resources.length!=1||!PermissionRequest.RESOURCE_AUDIO_CAPTURE.equals(resources[0])){request.deny();return;}if(checkSelfPermission(Manifest.permission.RECORD_AUDIO)==PackageManager.PERMISSION_GRANTED)request.grant(new String[]{PermissionRequest.RESOURCE_AUDIO_CAPTURE});else{if(microphone!=null)microphone.deny();microphone=request;requestPermissions(new String[]{Manifest.permission.RECORD_AUDIO},42);}});}
 @Override public void onPermissionRequestCanceled(PermissionRequest request){if(microphone==request)microphone=null;}
 @Override public boolean onCreateWindow(WebView v,boolean dialog,boolean gesture,android.os.Message message){if(!gesture)return false;WebView popup=new WebView(MainActivity.this);popup.setWebViewClient(new WebViewClient(){@Override public boolean shouldOverrideUrlLoading(WebView p,WebResourceRequest r){external(r.getUrl().toString());p.destroy();return true;}});((WebView.WebViewTransport)message.obj).setWebView(popup);message.sendToTarget();return true;}});
 web.setDownloadListener((url,ua,disposition,mime,length)->{if(!trusted(url))return;try{android.app.DownloadManager.Request r=new android.app.DownloadManager.Request(Uri.parse(url));String cookie=CookieManager.getInstance().getCookie(url);if(cookie!=null)r.addRequestHeader("Cookie",cookie);r.addRequestHeader("User-Agent",ua);r.setMimeType(mime);String name=URLUtil.guessFileName(url,disposition,mime).replaceAll("[^\\p{L}\\p{N}._ -]","_");r.setDestinationInExternalPublicDir(Environment.DIRECTORY_DOWNLOADS,name);r.setNotificationVisibility(android.app.DownloadManager.Request.VISIBILITY_VISIBLE_NOTIFY_COMPLETED);((android.app.DownloadManager)getSystemService(DOWNLOAD_SERVICE)).enqueue(r);}catch(Exception e){new AlertDialog.Builder(this).setMessage("Download failed. Please try again.").setPositiveButton("OK",null).show();}});
 web.loadUrl(ORIGIN+"/?pongy_app=android&client_version=0.19.0");}
 @Override protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(request==41&&files!=null){Uri[] selected=null;if(result==RESULT_OK&&data!=null){if(data.getClipData()!=null){int n=Math.min(4,data.getClipData().getItemCount());selected=new Uri[n];for(int i=0;i<n;i++)selected[i]=data.getClipData().getItemAt(i).getUri();}else if(data.getData()!=null)selected=new Uri[]{data.getData()};}files.onReceiveValue(selected);files=null;}}
 @Override public void onRequestPermissionsResult(int request,String[] permissions,int[] results){super.onRequestPermissionsResult(request,permissions,results);if(request==42&&microphone!=null){if(results.length>0&&results[0]==PackageManager.PERMISSION_GRANTED&&trusted(web.getUrl()))microphone.grant(new String[]{PermissionRequest.RESOURCE_AUDIO_CAPTURE});else microphone.deny();microphone=null;}}
 @Override public void onBackPressed(){if(web.canGoBack())web.goBack();else super.onBackPressed();}
 private void showOffline(){try(java.io.InputStream in=getAssets().open("offline.html")){java.io.ByteArrayOutputStream out=new java.io.ByteArrayOutputStream();byte[] buffer=new byte[8192];int n;while((n=in.read(buffer))!=-1)out.write(buffer,0,n);web.loadDataWithBaseURL(ORIGIN+"/",out.toString("UTF-8"),"text/html","UTF-8",null);}catch(java.io.IOException e){new AlertDialog.Builder(this).setMessage("No internet connection / Нет подключения к интернету").setPositiveButton("Retry / Повторить",(d,w)->web.loadUrl(ORIGIN+"/?pongy_app=android&client_version=0.19.0")).show();}}
 public final class AppSettingsBridge {@JavascriptInterface public void openAppSettings(){runOnUiThread(()->{if(!trusted(web.getUrl()))return;try{startActivity(new Intent(android.provider.Settings.ACTION_APPLICATION_DETAILS_SETTINGS,Uri.parse("package:"+getPackageName())));}catch(ActivityNotFoundException ignored){}});}}
 @Override protected void onPause(){CookieManager.getInstance().flush();super.onPause();}
 @Override protected void onDestroy(){if(files!=null)files.onReceiveValue(null);if(microphone!=null)microphone.deny();if(web!=null)web.destroy();super.onDestroy();}
}
